mapper.select:
SELECT e.id, e.name, d.dept_name AS department, p.pos_name AS position, e.entry_date, e.status FROM employee e INNER JOIN department d ON d.id = e.dept_id INNER JOIN position p ON p.id = e.position_id AND e.dept_id = p.dept_id
AND e.name LIKE CONCAT('%', #{dto.name}, '%')
AND e.dept_id = #{dto.deptId}
AND e.position_id = #{dto.positionId}
AND e.status = #{dto.status}
AND e.entry_date >= #{dto.entryStartDate}
AND e.entry_date <= #{dto.entryEndDate}
ORDER BY e.id DESC
